#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--, v--;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    // BFS from vertex 0 for parents, depths and an order where parents come first.
    vector<int> parent(n, -1), order{0};
    vector<long long> depth(n, 0);
    parent[0] = 0;
    for (size_t h = 0; h < order.size(); h++) {
        int u = order[h];
        for (int v : g[u])
            if (parent[v] < 0) {
                parent[v] = u;
                depth[v] = depth[u] + 1;
                order.push_back(v);
            }
    }
    vector<long long> sub(a);
    for (int i = n - 1; i >= 1; i--) sub[parent[order[i]]] += sub[order[i]];
    long long total = 0, root = 0;
    for (int i = 0; i < n; i++) {
        total += a[i];
        root += depth[i] * a[i];
    }
    // Moving the root across an edge: subtree gets 1 closer, the rest 1 farther.
    vector<long long> beauty(n);
    beauty[0] = root;
    long long best = root;
    for (int i = 1; i < n; i++) {
        int v = order[i];
        beauty[v] = beauty[parent[v]] + total - 2 * sub[v];
        best = max(best, beauty[v]);
    }
    printf("%lld\n", best);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Adjacency in CSR form.
        int[] eu = new int[n - 1], ev = new int[n - 1], deg = new int[n + 1];
        for (int i = 0; i < n - 1; i++) {
            eu[i] = nextInt() - 1;
            ev[i] = nextInt() - 1;
            deg[eu[i] + 1]++;
            deg[ev[i] + 1]++;
        }
        for (int i = 0; i < n; i++) deg[i + 1] += deg[i];
        int[] adj = new int[2 * (n - 1)], fill = Arrays.copyOf(deg, n);
        for (int i = 0; i < n - 1; i++) {
            adj[fill[eu[i]]++] = ev[i];
            adj[fill[ev[i]]++] = eu[i];
        }
        // BFS from vertex 0 for parents, depths and an order where parents come first.
        int[] parent = new int[n], order = new int[n];
        long[] depth = new long[n];
        Arrays.fill(parent, -1);
        parent[0] = 0;
        int size = 1;
        for (int h = 0; h < size; h++) {
            int u = order[h];
            for (int e = deg[u]; e < deg[u + 1]; e++) {
                int v = adj[e];
                if (parent[v] < 0) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    order[size++] = v;
                }
            }
        }
        long[] sub = a.clone();
        for (int i = n - 1; i >= 1; i--) sub[parent[order[i]]] += sub[order[i]];
        long total = 0, root = 0;
        for (int i = 0; i < n; i++) {
            total += a[i];
            root += depth[i] * a[i];
        }
        // Moving the root across an edge: subtree gets 1 closer, the rest 1 farther.
        long[] beauty = new long[n];
        beauty[0] = root;
        long best = root;
        for (int i = 1; i < n; i++) {
            int v = order[i];
            beauty[v] = beauty[parent[v]] + total - 2 * sub[v];
            best = Math.max(best, beauty[v]);
        }
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Adjacency in CSR form.
	eu := make([]int, n-1)
	ev := make([]int, n-1)
	deg := make([]int, n+1)
	for i := 0; i < n-1; i++ {
		eu[i], ev[i] = int(nextInt())-1, int(nextInt())-1
		deg[eu[i]+1]++
		deg[ev[i]+1]++
	}
	for i := 0; i < n; i++ {
		deg[i+1] += deg[i]
	}
	adj := make([]int, 2*(n-1))
	fill := append([]int(nil), deg[:n]...)
	for i := 0; i < n-1; i++ {
		adj[fill[eu[i]]] = ev[i]
		fill[eu[i]]++
		adj[fill[ev[i]]] = eu[i]
		fill[ev[i]]++
	}
	// BFS from vertex 0 for parents, depths and an order where parents come first.
	parent := make([]int, n)
	for i := range parent {
		parent[i] = -1
	}
	parent[0] = 0
	depth := make([]int64, n)
	order := make([]int, 0, n)
	order = append(order, 0)
	for h := 0; h < len(order); h++ {
		u := order[h]
		for e := deg[u]; e < deg[u+1]; e++ {
			v := adj[e]
			if parent[v] < 0 {
				parent[v] = u
				depth[v] = depth[u] + 1
				order = append(order, v)
			}
		}
	}
	sub := append([]int64(nil), a...)
	for i := n - 1; i >= 1; i-- {
		sub[parent[order[i]]] += sub[order[i]]
	}
	var total, root int64
	for i := 0; i < n; i++ {
		total += a[i]
		root += depth[i] * a[i]
	}
	// Moving the root across an edge: subtree gets 1 closer, the rest 1 farther.
	beauty := make([]int64, n)
	beauty[0] = root
	best := root
	for i := 1; i < n; i++ {
		v := order[i]
		beauty[v] = beauty[parent[v]] + total - 2*sub[v]
		best = max(best, beauty[v])
	}
	fmt.Println(best)
}
